# <<< SPEC

# >>> HINTS
# %%cargo
# - `cargo --list` is the authoritative subcommand list (`cargo --help` truncates it with `... See all commands with --list`). Declare every entry that has a description, skip `help`, and skip entries without a description (they are external commands). Entries listed as `alias: <cmd>` are aliases of that command.
# - This root supports external subcommands (`cargo <name>` runs `cargo-<name>`): add the root-only meta `external-subcommands`.
# <<< HINTS

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_add_feature() {
    local dep="${argc_dep_id[0]:-}"
    if [[ -z "$dep" ]]; then
        _choice_features
        return 0
    fi
    _argc_util_cache 300 _helper_add_feature_uncached "cargo-add-feature:${dep%%@*}"
}

_choice_clippy_args() {
    case "${argc__args[-2]:-}" in
        -A|-D|-F|-W|--allow|--deny|--forbid|--force-warn|--warn)
            _choice_lint
            return 0
            ;;
    esac
    command rustc -h 2>/dev/null | gawk '
        /^[[:space:]]+-/ {
            line = $0
            sub(/^[[:space:]]+/, "", line)
            sub(/[[:space:]][[:space:]].*/, "", line)
            count = split(line, parts, ",")
            for (i = 1; i <= count; i++) {
                flag = parts[i]
                sub(/^[[:space:]]+/, "", flag)
                sub(/[[:space:]].*/, "", flag)
                if (flag ~ /^-/) print flag
            }
        }
    '
}

_choice_dep_id() {
    _helper_cargo_metadata | jq -b -r '.packages[].dependencies[].name' 2>/dev/null
}

_choice_features() {
    _helper_cargo_metadata | jq -b -r '.packages[].features | keys[]' 2>/dev/null
}

_choice_installed_bin() {
    local crate="${argc_package:-${argc__positionals[0]:-}}"
    command cargo install --list 2>/dev/null | gawk -v crate="$crate" '
        /^[^[:space:]]+ v/ { in_block = (crate == "" || $1 == crate); next }
        in_block && /^[[:space:]]+[^[:space:]]+$/ { print $1 }
    '
}

_choice_installed_crate() {
    command cargo install --list 2>/dev/null | gawk '/^[^[:space:]]+ v[0-9]/ { print $1 }'
}

_choice_lint() {
    command clippy-driver -W help 2>/dev/null \
        | gawk '/^[[:space:]]+[a-z0-9:_-]+[[:space:]]+(allow|warn|deny|forbid)/ { print $1 }'
}

_choice_package() {
    _helper_cargo_metadata | jq -b -r '.packages[].name' 2>/dev/null
}

_choice_print() {
    command rustc --print help 2>&1 \
        | sed -n 's/.*valid print requests are: //p' \
        | tr ',' '\n' \
        | sed 's/^[[:space:]]*//; s/[[:space:]]*$//; s/`//g' \
        | grep -v '^$'
}

_choice_profile() {
    printf '%s\n' dev release test bench
    local root
    root="$(_helper_cargo_metadata | jq -b -r '.workspace_root // empty' 2>/dev/null)"
    [[ -n "$root" && -f "$root/Cargo.toml" ]] || return 0
    gawk '/^\[profile\./ { line=$0; sub(/^\[profile\./, "", line); sub(/\]$/, "", line); print line }' "$root/Cargo.toml"
}

_choice_registry() {
    printf '%s\n' crates-io
    local file
    for file in "${CARGO_HOME:-$HOME/.cargo}/config.toml" "${CARGO_HOME:-$HOME/.cargo}/config" \
        ./.cargo/config.toml ./.cargo/config; do
        [[ -f "$file" ]] || continue
        gawk '/^\[registries\./ { line=$0; sub(/^\[registries\./, "", line); sub(/\]$/, "", line); print line }' "$file"
    done
}

_choice_remote_crate() {
    [[ ${#ARGC_CWORD} -gt 2 ]] || return 0
    _argc_util_cache 60 _helper_remote_crate_uncached "cargo-remote-crate:$ARGC_CWORD"
}

_choice_rustfmt_options() {
    command -v rustfmt >/dev/null 2>&1 || return 0
    command rustfmt --help 2>/dev/null | gawk '
        /^[[:space:]]+-/ {
            gsub(/,/, "")
            for (i = 1; i <= NF; i++) {
                if ($i ~ /^--?[A-Za-z]/) print $i
            }
        }
    '
}

_choice_subcommand() {
    command cargo --list 2>/dev/null | gawk '
        /^[[:space:]]+[^[:space:]]+/ {
            if ($2 == "alias:" && $3 != "") next
            name = $1
            desc = $0
            sub(/^[[:space:]]+[^[:space:]]+[[:space:]]*/, "", desc)
            if (desc == "") print name
            else printf "%s\t%s\n", name, desc
        }
    '
}

_choice_target() {
    _argc_util_cache 3600 _helper_target_uncached rustc-target-list
}

_choice_target_bench() {
    _helper_cargo_metadata | jq -b -r '.packages[].targets[] | select(.kind[] == "bench") | .name' 2>/dev/null
}

_choice_target_bin() {
    _helper_cargo_metadata | jq -b -r '.packages[].targets[] | select(.kind[] == "bin") | .name' 2>/dev/null
}

_choice_target_example() {
    _helper_cargo_metadata | jq -b -r '.packages[].targets[] | select(.kind[] == "example") | .name' 2>/dev/null
}

_choice_target_test() {
    _helper_cargo_metadata | jq -b -r '.packages[].targets[] | select(.kind[] == "test") | .name' 2>/dev/null
}

_choice_testname() {
    _argc_util_cache 60 _helper_testname_uncached "cargo-testname:$PWD"
}

_choice_toolchain() {
    command -v rustup >/dev/null 2>&1 || return 0
    local host name
    host="$(command rustup show 2>/dev/null | sed -n 's/^Default host: //p')"
    command rustup toolchain list 2>/dev/null | sed 's/ (.*//' | while IFS= read -r name; do
        if [[ -n "$host" && "$name" == *-"$host" ]]; then
            printf '%s\n' "${name%-$host}"
        else
            printf '%s\n' "$name"
        fi
    done | gawk '!seen[$0]++'
}

_choice_z_flag() {
    command cargo -Z help 2>/dev/null | gawk '/^    -Z / { print $2 }'
}

_helper_add_feature_uncached() {
    local dep="${argc_dep_id[0]:-}"
    dep="${dep%%@*}"
    [[ -n "$dep" ]] || return 0
    command -v curl >/dev/null 2>&1 || return 0
    command curl -fsSL --max-time 8 \
        -A 'argc-completions (https://github.com/sigoden/argc-completions)' \
        "https://crates.io/api/v1/crates/$dep" \
        | jq -b -r '.versions[0].features | keys[]' 2>/dev/null
}

_helper_cargo_metadata() {
    _argc_util_cache 60 _helper_cargo_metadata_uncached "cargo-metadata:$PWD"
}

_helper_cargo_metadata_uncached() {
    command cargo metadata --no-deps --format-version 1 2>/dev/null
}

_helper_remote_crate_uncached() {
    local query="$ARGC_CWORD"
    [[ ${#query} -gt 2 ]] || return 0
    command -v curl >/dev/null 2>&1 || return 0
    query="$(printf '%s' "$query" | jq -b -R -r @uri)"
    command curl -fsSL --max-time 8 \
        -A 'argc-completions (https://github.com/sigoden/argc-completions)' \
        "https://crates.io/api/v1/crates?q=$query&per_page=20" \
        | jq -b -r '.crates[] | [.name, .description // ""] | @tsv' 2>/dev/null
}

_helper_target_uncached() {
    command rustc --print target-list 2>/dev/null
}

_helper_testname_uncached() {
    command cargo test -q -- --list 2>/dev/null \
        | gawk '/^[^[:space:]]+: test$/ { sub(/: test$/, ""); print }'
}
